// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title LotteryWorker
 * @notice Background job processor for lottery draws with async commitment scheme
 */
contract LotteryWorker is Ownable, ReentrancyGuard {
    struct Job {
        uint256 id;
        address requester;
        uint256 commitBlock;
        bytes32 commitHash;
        uint256 stake;
        bool resolved;
        uint256 result;
    }

    struct EntropyPool {
        bytes32 accumulator;
        uint256 lastUpdate;
        uint256 contributions;
    }

    mapping(uint256 => Job) public jobs;
    mapping(address => uint256[]) public userJobs;
    EntropyPool public entropyPool;

    uint256 public nextJobId;
    uint256 public constant MIN_STAKE = 0.01 ether;
    uint256 public constant COMMIT_DELAY = 2;
    // Strictly less than 256 so blockhash(job.commitBlock) is always valid at resolution.
    uint256 public constant MAX_REVEAL_WINDOW = 255;

    event JobSubmitted(uint256 indexed jobId, address indexed requester, uint256 commitBlock);
    event JobResolved(uint256 indexed jobId, uint256 result);
    event EntropyContributed(address indexed contributor, bytes32 entropy);

    constructor() {
        entropyPool.accumulator = keccak256(abi.encodePacked(block.timestamp, block.prevrandao, address(this)));
        entropyPool.lastUpdate = block.number;
        entropyPool.contributions = 0;
    }

    /**
     * @notice Contribute entropy to the shared pool
     * @param userEntropy User-provided randomness
     */
    function contributeEntropy(bytes32 userEntropy) external {
        entropyPool.accumulator = keccak256(abi.encodePacked(
            entropyPool.accumulator,
            userEntropy,
            msg.sender,
            block.number
        ));
        entropyPool.contributions++;
        entropyPool.lastUpdate = block.number;
        emit EntropyContributed(msg.sender, userEntropy);
    }

    /**
     * @notice Submit a new lottery job with commit-reveal scheme
     */
    function submitJob() external payable nonReentrant returns (uint256) {
        require(msg.value >= MIN_STAKE, "Insufficient stake");

        uint256 jobId = nextJobId++;
        uint256 commitBlock = block.number + COMMIT_DELAY;

        bytes32 commitHash = keccak256(abi.encodePacked(
            msg.sender,
            jobId,
            commitBlock,
            entropyPool.accumulator
        ));

        jobs[jobId] = Job({
            id: jobId,
            requester: msg.sender,
            commitBlock: commitBlock,
            commitHash: commitHash,
            stake: msg.value,
            resolved: false,
            result: 0
        });

        userJobs[msg.sender].push(jobId);
        emit JobSubmitted(jobId, msg.sender, commitBlock);
        return jobId;
    }

    /**
     * @notice Resolve a pending job - the async worker callback
     * @param jobId The job to resolve
     */
    function resolveJob(uint256 jobId) external nonReentrant {
        Job storage job = jobs[jobId];
        require(!job.resolved, "Already resolved");
        require(block.number > job.commitBlock, "Too early");
        require(block.number <= job.commitBlock + MAX_REVEAL_WINDOW, "Reveal window expired");
        require(msg.sender == job.requester || msg.sender == owner(), "Unauthorized");

        uint256 randomResult = _generateSecureRandom(job);
        job.result = randomResult % 1000000;
        job.resolved = true;

        // Pay out if winner (result < 1000 means 0.1% chance)
        if (job.result < 1000) {
            uint256 payout = job.stake * 100;
            if (address(this).balance >= payout) {
                (bool success, ) = job.requester.call{value: payout}("");
                require(success, "Transfer failed");
            }
        }

        emit JobResolved(jobId, job.result);
    }

    /**
     * @dev Internal secure random generation using commit-reveal + entropy pool
     * @notice Uses multiple entropy sources for unpredictability
     */
    function _generateSecureRandom(Job storage job) internal view returns (uint256) {
        // Combine multiple sources: blockhash from committed block, entropy pool,
        // job-specific data, and current block context
        bytes32 blockEntropy = blockhash(job.commitBlock);
        // Defensive: blockhash must be within the last 256 blocks; with
        // MAX_REVEAL_WINDOW = 255 this is always the case, but guard anyway.
        require(blockEntropy != bytes32(0), "Block entropy unavailable");

        // Derive the seed through iterative hashing for diffusion
        bytes32 seed = keccak256(abi.encodePacked(
            blockEntropy,
            job.commitHash,
            entropyPool.accumulator,
            block.prevrandao
        ));

        // Apply additional mixing rounds
        seed = _mixEntropy(seed, uint256(blockEntropy));

        return uint256(seed);
    }

    /**
     * @dev Entropy mixing function with multiple rounds
     * @param input The initial seed
     * @param auxData Additional data for mixing
     */
    function _mixEntropy(bytes32 input, uint256 auxData) internal view returns (bytes32) {
        bytes32 mixed = input;

        // Three rounds of mixing with different block-derived values
        for (uint256 i = 0; i < 3; i++) {
            mixed = keccak256(abi.encodePacked(
                mixed,
                auxData,
                block.prevrandao,
                blockhash(block.number - 1 - i),
                i
            ));
        }

        return mixed;
    }

    /**
     * @notice Batch resolve multiple jobs (async worker pattern)
     * @param jobIds Array of job IDs to resolve
     */
    function batchResolve(uint256[] calldata jobIds) external nonReentrant {
        require(msg.sender == owner(), "Only owner can batch resolve");
        for (uint256 i = 0; i < jobIds.length; i++) {
            Job storage job = jobs[jobIds[i]];
            if (!job.resolved && block.number > job.commitBlock && 
                block.number <= job.commitBlock + MAX_REVEAL_WINDOW) {
                uint256 randomResult = _generateSecureRandom(job);
                job.result = randomResult % 1000000;
                job.resolved = true;

                if (job.result < 1000) {
                    uint256 payout = job.stake * 100;
                    if (address(this).balance >= payout) {
                        (bool success, ) = job.requester.call{value: payout}("");
                        if (success) {
                            emit JobResolved(jobIds[i], job.result);
                        }
                    }
                } else {
                    emit JobResolved(jobIds[i], job.result);
                }
            }
        }
    }

    /**
     * @notice Get job details
     */
    function getJob(uint256 jobId) external view returns (Job memory) {
        return jobs[jobId];
    }

    /**
     * @notice Fund the contract for payouts
     */
    function fund() external payable {}

    receive() external payable {}
}
